                    {"action": "FadeIn", "target": "label_a", "params": {"run_time": 0.3}, "wait": 0.1},
                    {"action": "FadeIn", "target": "label_b", "params": {"run_time": 0.3}, "wait": 0.1},
                    {"action": "FadeIn", "target": "label_c", "params": {"run_time": 0.3}, "wait": 0.5},
                    {"action": "Write", "target": "formula", "params": {"run_time": 2.0}, "wait": 1.0}
