                        "params": {"side_length": 3.6, "color": "YELLOW", "fill_opacity": 0.3}
                    }
                ],
                "animations": [
                    {"action": "Create", "target": "big_square", "params": {"run_time": 1.0}, "wait": 0.5},
                    {"action": "FadeIn", "target": "tri1", "params": {"run_time": 0.5}, "wait": 0.2},
                    {"action": "FadeIn", "target": "tri2", "params": {"run_time": 0.5}, "wait": 0.2},
                    {"action": "FadeIn", "target": "tri3", "params": {"run_time": 0.5}, "wait": 0.2},
                    {"action": "FadeIn", "target": "tri4", "params": {"run_time": 0.5}, "wait": 0.5},
                    {"action": "FadeIn", "target": "inner_square", "params": {"run_time": 1.0}, "wait": 1.0}
                ],
                "narration": "我们构造一个边长为a加b的大正方形，在四个角各放置一个全等的直角三角形。中间空出的部分形成一个小正方形，它的边长正好是斜边c。",
