                        "name": "val_0",
                        "params": {"text": "3", "font_size": 32}
                    },
                    {
                        "type": "Text",
                        "name": "val_1",
                        "params": {"text": "7", "font_size": 32}
                    },
                    {
                        "type": "Text",
                        "name": "val_pivot",
                        "params": {"text": "5", "font_size": 32}
                    },
                    {
                        "type": "Arrow",
                        "name": "left_arrow",
                        "params": {"color": "GREEN"}
                    },
                    {
                        "type": "Arrow",
                        "name": "right_arrow",
                        "params": {"color": "ORANGE"}
                    }
                ],
                "animations": [
                    {"action": "Write", "target": "title", "params": {"run_time": 1.0}, "wait": 0.5},
                    {"action": "FadeIn", "target": "arr_0", "params": {"run_time": 0.3}, "wait": 0.1},
                    {"action": "FadeIn", "target": "arr_1", "params": {"run_time": 0.3}, "wait": 0.1},
