                "duration": 6.0,
                "source_node_id": "partition"
            }
        }
    ]
}


def get_scene_examples(subject: str, n: int = 1) -> list[dict[str, Any]]:
    """
    获取场景生成的Few-Shot示例

    Args:
        subject: 学科类型
        n: 示例数量

    Returns:
        示例列表
    """
    examples = SCENE_EXAMPLES.get(subject, SCENE_EXAMPLES.get("math", []))
    return examples[:n]


def format_scene_examples(subject: str, n: int = 1) -> str:
    """
    格式化场景示例为Prompt文本

    Args:
        subject: 学科类型
        n: 示例数量

    Returns:
        格式化的示例文本
    """
    import json
    examples = get_scene_examples(subject, n)

    parts = []
    for i, ex in enumerate(examples, 1):
        parts.append(f"""
### 示例 {i}

**输入节点**:
```json
{json.dumps(ex['input'], ensure_ascii=False, indent=2)}
```

**输出场景规格**:
```json
{json.dumps(ex['output'], ensure_ascii=False, indent=2)}
```
""")

    return "\n".join(parts)
